5	static void l2norm(const float* x, float* out, int n, int dim, float eps)
6	{
7	    for (int i = 0; i < n; i++)
8	    {
9	        const float* row_in = x + i * dim;
10	        float* row_out = out + i * dim;
11	
12	        float sum = 0.f;
13	        for (int j = 0; j < dim; j++)
14	        {
15	            sum += row_in[j] * row_in[j];
16	        }
17	        float inv_norm = 1.f / sqrtf(sum + eps);
18	
19	        for (int j = 0; j < dim; j++)
20	        {
21	            row_out[j] = row_in[j] * inv_norm;
22	        }
23	    }
24	}
25	
26	static float sigmoidf(float x)
27	{
28	    return 1.f / (1.f + expf(-x));
29	}
30	
31	static float softplusf(float x)
32	{
33	    if (x > 20.f)
34	        return x;
35	    if (x < -20.f)
36	        return expf(x);
37	    return logf(1.f + expf(x));
38	}
