40	static void torch_recurrent_gated_delta_rule(
41	    const float* query, const float* key, const float* value,
42	    const float* g, const float* beta,
43	    float* core_attn_out,
44	    float* last_recurrent_state,
45	    int batch_size, int num_heads, int seq_len,
46	    int k_head_dim, int v_head_dim,
47	    bool use_qk_l2norm_in_kernel)
48	{
49	    std::vector<float> query_norm;
50	    std::vector<float> key_norm;
51	
52	    const float* q_ptr = query;
53	    const float* k_ptr = key;
54	
55	    int qk_size = batch_size * num_heads * seq_len * k_head_dim;
56	    if (use_qk_l2norm_in_kernel)
57	    {
58	        query_norm.resize(qk_size);
59	        key_norm.resize(qk_size);
60	
61	        l2norm(query, query_norm.data(), batch_size * num_heads * seq_len, k_head_dim, 1e-6f);
62	        l2norm(key, key_norm.data(), batch_size * num_heads * seq_len, k_head_dim, 1e-6f);
63	
64	        q_ptr = query_norm.data();
65	        k_ptr = key_norm.data();
66	    }
67	
68	    float scale = 1.f / sqrtf((float)k_head_dim);
69	
70	    memset(core_attn_out, 0, batch_size * num_heads * seq_len * v_head_dim * sizeof(float));
71	
72	    for (int t = 0; t < seq_len; t++)
73	    {
74	        for (int b = 0; b < batch_size; b++)
75	        {
76	            for (int h = 0; h < num_heads; h++)
77	            {
78	                const float* q_t = q_ptr + ((b * num_heads + h) * seq_len + t) * k_head_dim;
79	                const float* k_t = k_ptr + ((b * num_heads + h) * seq_len + t) * k_head_dim;
80	                const float* v_t = value + ((b * num_heads + h) * seq_len + t) * v_head_dim;
81	
82	                float g_t = g[(b * num_heads + h) * seq_len + t];
83	                float beta_t = beta[(b * num_heads + h) * seq_len + t];
84	
85	                float* state = last_recurrent_state + (b * num_heads + h) * k_head_dim * v_head_dim;
86	                float* out_t = core_attn_out + ((b * num_heads + h) * seq_len + t) * v_head_dim;
87	
88	                float g_t_exp = expf(g_t);
89	
90	                for (int i = 0; i < k_head_dim * v_head_dim; i++)
91	                {
92	                    state[i] *= g_t_exp;
93	                }
94	
95	                std::vector<float> kv_mem(v_head_dim, 0.f);
96	                for (int dv = 0; dv < v_head_dim; dv++)
97	                {
98	                    for (int dk = 0; dk < k_head_dim; dk++)
99	                    {
100	                        kv_mem[dv] += state[dk * v_head_dim + dv] * k_t[dk];
101	                    }
102	                }
103	
104	                std::vector<float> delta(v_head_dim);
105	                for (int dv = 0; dv < v_head_dim; dv++)
106	                {
107	                    delta[dv] = (v_t[dv] - kv_mem[dv]) * beta_t;
108	                }
109	
110	                for (int dk = 0; dk < k_head_dim; dk++)
111	                {
112	                    for (int dv = 0; dv < v_head_dim; dv++)
113	                    {
114	                        state[dk * v_head_dim + dv] += k_t[dk] * delta[dv];
115	                    }
116	                }
117	
118	                for (int dv = 0; dv < v_head_dim; dv++)
119	                {
120	                    float sum = 0.f;
121	                    for (int dk = 0; dk < k_head_dim; dk++)
122	                    {
123	                        sum += state[dk * v_head_dim + dv] * q_t[dk] * scale;
124	                    }
125	                    out_t[dv] = sum;
126	                }
127	            }
128	        }
129	    }
130	}
131	
132	GatedDeltaRule::GatedDeltaRule()
133	{
134	    one_blob_only = false;
135	    support_inplace = false;
136	
137	    num_k_heads = 128;
138	    num_v_heads = 128;
139	}
