141	int GatedDeltaRule::forward(const std::vector<ncnn::Mat>& bottom_blobs, std::vector<ncnn::Mat>& top_blobs, const ncnn::Option& opt) const
142	{
143	    const ncnn::Mat& A_log = bottom_blobs[0];
144	    const ncnn::Mat& dt_bias = bottom_blobs[1];
145	    const ncnn::Mat& b = bottom_blobs[2];
146	    const ncnn::Mat& a = bottom_blobs[3];
147	    const ncnn::Mat& query = bottom_blobs[4];
148	    const ncnn::Mat& key = bottom_blobs[5];
149	    const ncnn::Mat& value = bottom_blobs[6];
150	    const ncnn::Mat& initial_state = bottom_blobs[7];
151	
152	    int num_heads = query.h;
153	    int seq_len = query.c;
154	    int k_head_dim = query.w;
155	    int v_head_dim = value.w;
156	
157	    bool use_qk_l2norm_in_kernel = true;
158	
159	    ncnn::Mat& top_blob = top_blobs[0];
160	    top_blob.create(k_head_dim, num_heads, seq_len, 4u, opt.blob_allocator);
161	
162	    ncnn::Mat& state_out = top_blobs[1];
163	    state_out.create(v_head_dim, k_head_dim, num_heads, 4u, opt.blob_allocator);
164	
165	    if (top_blob.empty() || state_out.empty())
166	        return -100;
167	
168	    const float* query_data = (const float*)query.data;
169	    const float* key_data = (const float*)key.data;
170	    const float* value_data = (const float*)value.data;
171	
172	    std::vector<float> query_t(num_heads * seq_len * k_head_dim);
173	    std::vector<float> key_t(num_heads * seq_len * k_head_dim);
174	    std::vector<float> value_t(num_heads * seq_len * v_head_dim);
175	
176	    for (int t = 0; t < seq_len; t++)
177	    {
178	        for (int h = 0; h < num_heads; h++)
179	        {
180	            for (int d = 0; d < k_head_dim; d++)
181	            {
182	                int src_idx = (t * num_heads + h) * k_head_dim + d;
183	                int dst_idx = (h * seq_len + t) * k_head_dim + d;
184	                query_t[dst_idx] = query_data[src_idx];
185	                key_t[dst_idx] = key_data[src_idx];
186	            }
187	            for (int d = 0; d < v_head_dim; d++)
188	            {
189	                int src_idx = (t * num_heads + h) * v_head_dim + d;
190	                int dst_idx = (h * seq_len + t) * v_head_dim + d;
191	                value_t[dst_idx] = value_data[src_idx];
192	            }
193	        }
194	    }
195	
196	    const float* b_data = (const float*)b.data;
197	    const float* a_data = (const float*)a.data;
198	    const float* A_log_data = (const float*)A_log.data;
199	    const float* dt_bias_data = (const float*)dt_bias.data;
200	
201	    std::vector<float> beta(num_heads * seq_len);
202	    std::vector<float> g(num_heads * seq_len);
203	
204	    for (int h = 0; h < num_heads; h++)
205	    {
206	        for (int t = 0; t < seq_len; t++)
207	        {
208	            float b_val = b_data[t * num_heads + h];
209	            beta[h * seq_len + t] = sigmoidf(b_val);
210	        }
211	    }
212	
213	    for (int h = 0; h < num_heads; h++)
214	    {
215	        float A_log_val = A_log_data[h];
216	        float dt_bias_val = dt_bias_data[h];
217	        float exp_A = expf(A_log_val);
218	
219	        for (int t = 0; t < seq_len; t++)
220	        {
221	            float a_val = a_data[t * num_heads + h];
222	            float sp_val = softplusf(a_val + dt_bias_val);
223	            g[h * seq_len + t] = -exp_A * sp_val;
224	        }
225	    }
226	
227	    int batch_size = 1;
228	
229	    std::vector<float> core_attn_out(num_heads * seq_len * v_head_dim);
230	    std::vector<float> last_recurrent_state(num_heads * k_head_dim * v_head_dim);
231	
232	    if (!initial_state.empty())
233	    {
234	        memcpy(last_recurrent_state.data(), initial_state.data,
235	               num_heads * k_head_dim * v_head_dim * sizeof(float));
236	    }
237	    else
238	    {
239	        memset(last_recurrent_state.data(), 0,
240	               num_heads * k_head_dim * v_head_dim * sizeof(float));
241	    }
242	
243	    torch_recurrent_gated_delta_rule(
244	        query_t.data(), key_t.data(), value_t.data(),
245	        g.data(), beta.data(),
246	        core_attn_out.data(),
247	        last_recurrent_state.data(),
248	        batch_size, num_heads, seq_len,
249	        k_head_dim, v_head_dim,
250	        use_qk_l2norm_in_kernel);
251	
252	    float* top_data = (float*)top_blob.data;
253	    for (int h = 0; h < num_heads; h++)
254	    {
255	        for (int t = 0; t < seq_len; t++)
256	        {
257	            for (int d = 0; d < v_head_dim; d++)
258	            {
259	                int src_idx = (h * seq_len + t) * v_head_dim + d;
260	                int dst_idx = (t * num_heads + h) * v_head_dim + d;
261	                top_data[dst_idx] = core_attn_out[src_idx];
262	            }
263	        }
264	    }
265	
266	    memcpy((float*)state_out.data, last_recurrent_state.data(),
267	           num_heads * k_head_dim * v_head_dim * sizeof(float));
268	
269	    return 0;
270	}
271	
272	ShortConv::ShortConv()
273	{
274	    one_blob_only = false;
275	    support_inplace = false;
276	}
277	
278	int ShortConv::forward(const std::vector<ncnn::Mat>& bottom_blobs, std::vector<ncnn::Mat>& top_blobs, const ncnn::Option& opt) const
279	{
280	    const ncnn::Mat& weight_mat = bottom_blobs[0];
281	    const ncnn::Mat& mixed_qkv = bottom_blobs[1];
282	    const ncnn::Mat& conv_state = bottom_blobs[2];
283	
284	    int seq_len = mixed_qkv.h;
285	    int groups = mixed_qkv.w;
286	    int kernel_size = weight_mat.w;
287	
288	    ncnn::Mat stated_mixed_qkv;
289	    if (conv_state.empty())
290	    {
291	        stated_mixed_qkv.create(groups, kernel_size - 1 + seq_len, 4u, opt.blob_allocator);
292	        memset(stated_mixed_qkv.row(0), 0, (kernel_size - 1) * groups * sizeof(float));
293	        memcpy(stated_mixed_qkv.row(kernel_size - 1), mixed_qkv, mixed_qkv.h * groups * sizeof(float));
294	    }
295	    else
296	    {
297	        stated_mixed_qkv.create(groups, conv_state.h + seq_len, 4u, opt.blob_allocator);
298	        memcpy(stated_mixed_qkv.row(0), conv_state, conv_state.h * groups * sizeof(float));
299	        memcpy(stated_mixed_qkv.row(conv_state.h), mixed_qkv, mixed_qkv.h * groups * sizeof(float));
300	    }
301	
302	    int state_len = kernel_size;
303	    int total_len = conv_state.empty() ? (kernel_size - 1 + seq_len) : (conv_state.h + seq_len);
304	    ncnn::Mat last_conv_state(groups, state_len, 4u, opt.blob_allocator);
305	    memcpy(last_conv_state.data, stated_mixed_qkv.row(total_len - state_len),
306	           state_len * groups * sizeof(float));
307	
308	    ncnn::Mat& top_blob = top_blobs[0];
309	    top_blob.create(groups, seq_len, 4u, opt.blob_allocator);
310	
311	    #pragma omp parallel for num_threads(opt.num_threads)
312	    for (int g = 0; g < groups; g++)
313	    {
314	        const float* w_ptr = weight_mat.channel(g);
315	
316	        for (int i = 0; i < seq_len; i++)
317	        {
318	            float sum = 0.f;
319	
320	            int prefix_len = conv_state.empty() ? (kernel_size - 1) : conv_state.h;
321	            int base = prefix_len + i;
322	
323	            for (int k = 0; k < kernel_size; k++)
324	            {
325	                int src_i = base - (kernel_size - 1) + k;
326	                sum += stated_mixed_qkv.row(src_i)[g] * w_ptr[k];
327	            }
328	
329	            top_blob.row(i)[g] = sum * (1.f / (1.f + expf(-sum)));
330	        }
331	    }
332	
333	    top_blobs[1] = last_conv_state;
334	
335	    return 0;
336	}
337	
338	static ncnn::Layer* GatedDeltaRule_creator(void*)
339	{
340	    return new GatedDeltaRule;
341	}
342	
343	static void GatedDeltaRule_destroyer(ncnn::Layer* layer, void*)
344	{
345	    delete layer;
346	}
347	
348	static ncnn::Layer* ShortConv_creator(void*)
349	{
350	    return new ShortConv;
351	}
352	
353	static void ShortConv_destroyer(ncnn::Layer* layer, void*)
354	{
355	    delete layer;
356	}
357	
358	void register_gdr_layers(ncnn::Net& net)
359	{
360	    net.register_custom_layer("GatedDeltaRule", GatedDeltaRule_creator, GatedDeltaRule_destroyer);
361	    net.register_custom_layer("ShortConv", ShortConv_creator, ShortConv_destroyer);
362	}

